const pgRow = $input.first()?.json || {};
const pgOk = pgRow.ok === 1 && !pgRow.error;

const checks = [
  { name: 'Homepage', url: 'http://homepage:3000/', headers: { Host: 'homelab' }, maxStatus: 399 },
  { name: 'Grafana', url: 'http://grafana:3000/api/health', maxStatus: 299 },
  { name: 'Gitea', url: 'http://gitea:3000/api/healthz', maxStatus: 299 },
  { name: 'Prometheus', url: 'http://prometheus:9090/-/healthy', maxStatus: 299 },
  { name: 'cAdvisor', url: 'http://cadvisor:8080/healthz', maxStatus: 299 },
  { name: 'AdGuard Home', url: 'http://adguard-home:80/', maxStatus: 399 },
  { name: 'Nginx Proxy Manager', url: 'http://nginx-proxy-manager:81/api/', maxStatus: 299 },
];

const downDetails = [];
if (!pgOk) {
  downDetails.push(`• **PostgreSQL (postgres-force)** : ${pgRow.error?.message || 'requête SELECT 1 échouée'}`);
}

for (const svc of checks) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: svc.url,
      headers: svc.headers || {},
      timeout: 5000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    const code = Number(res?.statusCode ?? 0);
    if (!code || code > svc.maxStatus) {
      downDetails.push(`• **${svc.name}** : HTTP ${code || 'inconnu'}`);
    }
  } catch (err) {
    downDetails.push(`• **${svc.name}** : ${err.message || 'injoignable'}`);
  }
}

const downNames = downDetails
  .map((line) => line.match(/\*\*(.+?)\*\*/)?.[1] || line)
  .sort();

const staticData = $getWorkflowStaticData('global');
const prevDown = Array.isArray(staticData.prevDown) ? staticData.prevDown : [];

if (JSON.stringify(downNames) === JSON.stringify(prevDown)) {
  return [];
}

staticData.prevDown = downNames;

if (downDetails.length > 0) {
  const msg = [
    '🚨 **Alerte Homelab — Service(s) indisponible(s)**',
    ...downDetails,
  ].join('\n').slice(0, 1900);
  return [{ json: { message: msg, down: downNames } }];
}

return [{
  json: {
    message: '✅ **Homelab rétabli** — Tous les services surveillés répondent normalement.',
    down: [],
  },
}];
